ZXN_PROGPAGE	equ 0		; the Next's 8K page the program starts in (#0000): its six are ZXN_PROGPAGE .. + 5 (20261116-7: it was 16)
ZXN_FIRSTBANK	equ 2		; first free 16K bank (page 4), above the program/screen/low banks
