fn_e3w_lib_ewp_end:		; E3W.cls 310
            call fn_e3w_lib_ew_done		; E3W.cls 311
            pop ix		; E3W.cls 312
            pop iy		; E3W.cls 313
            ret		; E3W.cls 314
fn_e3w_lib_ewp_pj:                             ; the record at IX on the screen: HL = x, DE = y [315]
            ld l, (ix + 0)		; E3W.cls 316
            ld h, (ix + 1)		; E3W.cls 317
            ld e, (ix + 2)		; E3W.cls 318
            ld d, (ix + 3)		; E3W.cls 319
