; ew_cut3: the edge ew_p - ew_q cut to the planes in E3's cmask (as its clipper's: 0 z >= 16, 1
; z >= x / 4... the guard band) -> carry: wholly outside one
fn_e3w_lib_ew_cut3:		; E3W.cls 325
