            jr nc, fn_e3w_lib_ec_q		; E3W.cls 347
            ld hl, fn_e3w_lib_ew_p             ; p outside: p moved to where it crosses [348]
            ld de, fn_e3w_lib_ew_q		; E3W.cls 349
            ld bc, (fn_e3w_lib_ew_dp)		; E3W.cls 350
            ld ix, (fn_e3w_lib_ew_dq)		; E3W.cls 351
            call fn_e3w_lib_ec_cut		; E3W.cls 352
            jr fn_e3w_lib_ec_nx		; E3W.cls 353
fn_e3w_lib_ec_q:		; E3W.cls 354
            bit 7, h		; E3W.cls 355
            jr z, fn_e3w_lib_ec_nx		; E3W.cls 356
            ld hl, fn_e3w_lib_ew_q             ; q outside [357]
            ld de, fn_e3w_lib_ew_p		; E3W.cls 358
            ld bc, (fn_e3w_lib_ew_dq)		; E3W.cls 359
            ld ix, (fn_e3w_lib_ew_dp)		; E3W.cls 360
