            jr nz, fn_e3w_lib_ecd_1		; E3W.cls 374
            ld l, (ix + 4)		; E3W.cls 375
            ld h, (ix + 5)		; E3W.cls 376
            ld de, -16		; E3W.cls 377
            add hl, de		; E3W.cls 378
            ret		; E3W.cls 379
fn_e3w_lib_ecd_1:		; E3W.cls 380
            ld e, (ix + 0)		; E3W.cls 381
            ld d, (ix + 1)		; E3W.cls 382
            cp 3		; E3W.cls 383
            jr c, fn_e3w_lib_ecd_x		; E3W.cls 384
            ld e, (ix + 2)		; E3W.cls 385
            ld d, (ix + 3)		; E3W.cls 386
fn_e3w_lib_ecd_x:		; E3W.cls 387
            sra d		; E3W.cls 388
            rr e		; E3W.cls 389
            sra d		; E3W.cls 390
            rr e		; E3W.cls 391
            ld l, (ix + 4)		; E3W.cls 392
            ld h, (ix + 5)		; E3W.cls 393
            bit 0, a		; E3W.cls 394
            jr z, fn_e3w_lib_ecd_add		; E3W.cls 395
            or a		; E3W.cls 396
            sbc hl, de		; E3W.cls 397
            ret		; E3W.cls 398
fn_e3w_lib_ecd_add:		; E3W.cls 399
            add hl, de		; E3W.cls 400
            ret		; E3W.cls 401
; ec_cut: the record at HL (outside, its distance BC) moved toward the one at DE (inside, its
; distance IX) to where the edge crosses: t = |out| / (|out| + |in|) (E3's udivf), each part
; out + (in - out) t (E3's smul)
fn_e3w_lib_ec_cut:		; E3W.cls 405
            ld (fn_e3w_lib_ec_o), hl		; E3W.cls 406
            ld (fn_e3w_lib_ec_i), de		; E3W.cls 407
            ld h, b		; E3W.cls 408
            ld l, c		; E3W.cls 409
            call fn_e3_lib_absh		; E3W.cls 410
            push hl		; E3W.cls 411
            push ix		; E3W.cls 412
            pop hl		; E3W.cls 413
            call fn_e3_lib_absh		; E3W.cls 414
            pop de		; E3W.cls 415
            add hl, de		; E3W.cls 416
            ex de, hl               ; HL = |out|, DE = the sum [417]
            call fn_e3_lib_udivf		; E3W.cls 418
            ld (fn_e3w_lib_ec_t), hl		; E3W.cls 419
            ld b, 3		; E3W.cls 420
fn_e3w_lib_ecc_lp:		; E3W.cls 421
            push bc		; E3W.cls 422
            ld hl, (fn_e3w_lib_ec_o)		; E3W.cls 423
            ld e, (hl)		; E3W.cls 424
            inc hl		; E3W.cls 425
            ld d, (hl)              ; out [426]
            ld hl, (fn_e3w_lib_ec_i)		; E3W.cls 427
            ld a, (hl)		; E3W.cls 428
            inc hl		; E3W.cls 429
            ld h, (hl)		; E3W.cls 430
            ld l, a                 ; in [431]
            push de		; E3W.cls 432
            or a		; E3W.cls 433
            sbc hl, de		; E3W.cls 434
            ld b, h		; E3W.cls 435
            ld c, l		; E3W.cls 436
            ld de, (fn_e3w_lib_ec_t)		; E3W.cls 437
            call fn_e3_lib_smul		; E3W.cls 438
            pop de		; E3W.cls 439
            add hl, de		; E3W.cls 440
            ex de, hl		; E3W.cls 441
            ld hl, (fn_e3w_lib_ec_o)		; E3W.cls 442
            ld (hl), e		; E3W.cls 443
            inc hl		; E3W.cls 444
            ld (hl), d		; E3W.cls 445
            inc hl		; E3W.cls 446
            ld (fn_e3w_lib_ec_o), hl		; E3W.cls 447
            ld hl, (fn_e3w_lib_ec_i)		; E3W.cls 448
            inc hl		; E3W.cls 449
            inc hl		; E3W.cls 450
            ld (fn_e3w_lib_ec_i), hl		; E3W.cls 451
            pop bc		; E3W.cls 452
            djnz fn_e3w_lib_ecc_lp		; E3W.cls 453
            ret		; E3W.cls 454
fn_e3w_lib_ec_o:       dw 0		; E3W.cls 455
fn_e3w_lib_ec_i:       dw 0		; E3W.cls 456
fn_e3w_lib_ec_t:       dw 0		; E3W.cls 457
fn_e3w_lib_ew_m:       db 0		; E3W.cls 458
fn_e3w_lib_ew_pl:      db 0		; E3W.cls 459
fn_e3w_lib_ew_dp:      dw 0		; E3W.cls 460
fn_e3w_lib_ew_dq:      dw 0		; E3W.cls 461
fn_e3w_lib_ew_p:       ds 6		; E3W.cls 462
fn_e3w_lib_ew_q:       ds 6		; E3W.cls 463
; ew_start: the colour (the low byte of E3's pc), no third mapped yet
fn_e3w_lib_ew_start:		; E3W.cls 465
            ld a, (var_e3_pc)		; E3W.cls 466
            ld (fn_e3w_lib_ew_col), a		; E3W.cls 467
            ld a, 255		; E3W.cls 468
            ld (fn_e3w_lib_ew_cur3), a		; E3W.cls 469
            ret		; E3W.cls 470
; ew_done: E3's data pages back in slots 6 and 7, as its filler leaves them
fn_e3w_lib_ew_done:		; E3W.cls 472
            ld a, (fn_e3_lib_dpage)		; E3W.cls 473
            db #ED, #92, #56		; E3W.cls 474
            inc a		; E3W.cls 475
            db #ED, #92, #57		; E3W.cls 476
            ret		; E3W.cls 477
; ew_map: A = a third (0-2) of the buffer being drawn (E3's back): its two pages to slots 6, 7
fn_e3w_lib_ew_map:		; E3W.cls 479
            ld (fn_e3w_lib_ew_cur3), a		; E3W.cls 480
            push bc		; E3W.cls 481
            add a, a		; E3W.cls 482
            ld b, a		; E3W.cls 483
            ld a, (var_e3_back)		; E3W.cls 484
            add a, a		; E3W.cls 485
            add a, b		; E3W.cls 486
            db #ED, #92, #56		; E3W.cls 487
            inc a		; E3W.cls 488
            db #ED, #92, #57		; E3W.cls 489
            pop bc		; E3W.cls 490
