fn_e3w_lib_ew_k:       db 0		; E3W.cls 492
fn_e3w_lib_ew_ip:      dw 0		; E3W.cls 493
fn_e3w_lib_ew_lst:     ds 64                   ; ew_ffi's list of points, copied [494]
fn_e3w_lib_ew_px:      dw 0		; E3W.cls 495
fn_e3w_lib_ew_py:      dw 0		; E3W.cls 496
fn_e3w_lib_ew_ax:      dw 0                    ; a line: from [497]
fn_e3w_lib_ew_ay:      dw 0		; E3W.cls 498
fn_e3w_lib_ew_bx:      dw 0                    ; to [499]
fn_e3w_lib_ew_by:      dw 0		; E3W.cls 500
fn_e3w_lib_ew_lx0:     db 0                    ; the line cut to the screen (bytes) [501]
fn_e3w_lib_ew_ly0:     db 0		; E3W.cls 502
fn_e3w_lib_ew_lx1:     db 0		; E3W.cls 503
fn_e3w_lib_ew_ly1:     db 0		; E3W.cls 504
fn_e3w_lib_ew_col:     db 0		; E3W.cls 505
fn_e3w_lib_ew_cur3:    db 255		; E3W.cls 506
fn_e3w_lib_ew_pc:      db 8		; E3W.cls 507
fn_e3w_lib_ew_full:    db 1                    ; (the box is the whole screen) [508]
fn_e3w_lib_ew_wx0:     dw 0                    ; the box: the screen [509]
fn_e3w_lib_ew_wy0:     dw 0		; E3W.cls 510
fn_e3w_lib_ew_wx1:     dw 255		; E3W.cls 511
fn_e3w_lib_ew_wy1:     dw 191		; E3W.cls 512
fn_e3w_lib_ew_tmp:     ds 4		; E3W.cls 513
; ============================================================================ the arithmetic and
; the lines (BASTION RUN's line engine's)
fn_e3w_lib_ew_neghl:		; E3W.cls 516
            xor a		; E3W.cls 517
            sub l		; E3W.cls 518
            ld l, a		; E3W.cls 519
            sbc a, a		; E3W.cls 520
            sub h		; E3W.cls 521
            ld h, a		; E3W.cls 522
            ret		; E3W.cls 523
; umul16x8: HL x A (unsigned) -> A:HL (24 bits; uses DE)
; um16: HL x DE (unsigned) -> HL:DE (32 bits; uses BC, A)
fn_e3w_lib_ew_um16:		; E3W.cls 526
            ld b, h		; E3W.cls 527
            ld c, l                 ; BC = x [528]
            ld a, e		; E3W.cls 529
            ld l, d                 ; a = y0, l = y1 [530]
            ld d, c		; E3W.cls 531
            ld e, a		; E3W.cls 532
            mul d, e                ; x0 y0 [533]
            push de		; E3W.cls 534
            ld d, b		; E3W.cls 535
            ld e, a		; E3W.cls 536
            mul d, e                ; x1 y0 [537]
            ld a, l                 ; y1 [538]
            ld h, d		; E3W.cls 539
            ld l, e                 ; HL = x1 y0 [540]
            ld d, c		; E3W.cls 541
            ld e, a		; E3W.cls 542
            mul d, e                ; x0 y1 [543]
            add hl, de              ; the middle (17 bits) [544]
            push af                 ; its carry [545]
            ld d, b		; E3W.cls 546
            ld e, a		; E3W.cls 547
            mul d, e                ; x1 y1 [548]
            pop af		; E3W.cls 549
            jr nc, fn_e3w_lib_wum16a		; E3W.cls 550
            inc d		; E3W.cls 551
fn_e3w_lib_wum16a:		; E3W.cls 552
            ld a, h                 ; the middle's high byte [553]
            ld b, l                 ; its low byte [554]
            ex de, hl               ; HL = x1 y1 (+ the middle's carry << 8) [555]
            ld e, a		; E3W.cls 556
            ld d, 0		; E3W.cls 557
            add hl, de              ; + the middle >> 8 [558]
            pop de                  ; x0 y0 [559]
            ld a, d		; E3W.cls 560
            add a, b                ; + the middle's low byte << 8 [561]
            ld d, a		; E3W.cls 562
            ret nc		; E3W.cls 563
            inc hl		; E3W.cls 564
            ret		; E3W.cls 565
; udiv: HL:DE / BC (unsigned, HL < BC) -> DE (the quotient), HL (what's left)
; udiv: HL:DE / BC (unsigned, HL < BC) -> DE (the quotient), HL (what's left)
fn_e3w_lib_ew_udiv:		; E3W.cls 568
            ld a, 16		; E3W.cls 569
fn_e3w_lib_wud_lp:		; E3W.cls 570
            sla e		; E3W.cls 571
            rl d		; E3W.cls 572
            adc hl, hl		; E3W.cls 573
            jr c, fn_e3w_lib_wud_sub		; E3W.cls 574
            sbc hl, bc		; E3W.cls 575
            jr nc, fn_e3w_lib_wud_one		; E3W.cls 576
            add hl, bc		; E3W.cls 577
            dec a		; E3W.cls 578
            jr nz, fn_e3w_lib_wud_lp		; E3W.cls 579
            ret		; E3W.cls 580
fn_e3w_lib_wud_sub:		; E3W.cls 581
            or a		; E3W.cls 582
            sbc hl, bc		; E3W.cls 583
fn_e3w_lib_wud_one:		; E3W.cls 584
            inc e		; E3W.cls 585
            dec a		; E3W.cls 586
            jr nz, fn_e3w_lib_wud_lp		; E3W.cls 587
            ret		; E3W.cls 588
; muldiv: HL = HL x DE / BC (signed; |DE| <= |BC| so it fits)
fn_e3w_lib_ew_muldiv:		; E3W.cls 590
            ld a, h		; E3W.cls 591
            xor d		; E3W.cls 592
            xor b		; E3W.cls 593
            push af                 ; the sign [594]
            bit 7, h		; E3W.cls 595
            call nz, fn_e3w_lib_ew_neghl		; E3W.cls 596
            bit 7, d		; E3W.cls 597
            jr z, fn_e3w_lib_wmd1		; E3W.cls 598
            ex de, hl		; E3W.cls 599
            call fn_e3w_lib_ew_neghl		; E3W.cls 600
            ex de, hl		; E3W.cls 601
fn_e3w_lib_wmd1:		; E3W.cls 602
            bit 7, b		; E3W.cls 603
            jr z, fn_e3w_lib_wmd2		; E3W.cls 604
            xor a		; E3W.cls 605
            sub c		; E3W.cls 606
            ld c, a		; E3W.cls 607
            sbc a, a		; E3W.cls 608
            sub b		; E3W.cls 609
            ld b, a		; E3W.cls 610
fn_e3w_lib_wmd2:		; E3W.cls 611
            push bc		; E3W.cls 612
            call fn_e3w_lib_ew_um16             ; HL:DE [613]
            pop bc		; E3W.cls 614
            ld a, h		; E3W.cls 615
            or l		; E3W.cls 616
            jr z, fn_e3w_lib_wmd3		; E3W.cls 617
            or a		; E3W.cls 618
            sbc hl, bc		; E3W.cls 619
            add hl, bc		; E3W.cls 620
            jr nc, fn_e3w_lib_wmd_big           ; (shouldn't: |DE| <= |BC|) [621]
fn_e3w_lib_wmd3:		; E3W.cls 622
            call fn_e3w_lib_ew_udiv		; E3W.cls 623
            ex de, hl		; E3W.cls 624
            pop af		; E3W.cls 625
            bit 7, a		; E3W.cls 626
            ret z		; E3W.cls 627
            jp fn_e3w_lib_ew_neghl		; E3W.cls 628
fn_e3w_lib_wmd_big:		; E3W.cls 629
            ld hl, 32767		; E3W.cls 630
            pop af		; E3W.cls 631
            bit 7, a		; E3W.cls 632
            ret z		; E3W.cls 633
            jp fn_e3w_lib_ew_neghl		; E3W.cls 634
; ew_code: HL = x, DE = y -> A = the box's outcode: 1 left, 2 right, 4 above, 8 below (HL, DE
; kept; B used)
fn_e3w_lib_ew_code:		; E3W.cls 637
            push hl		; E3W.cls 638
            push de		; E3W.cls 639
            ld b, 0		; E3W.cls 640
            push hl		; E3W.cls 641
            ld de, (fn_e3w_lib_ew_wx0)		; E3W.cls 642
            or a		; E3W.cls 643
            sbc hl, de		; E3W.cls 644
            pop hl		; E3W.cls 645
            jp p, fn_e3w_lib_wvco1		; E3W.cls 646
            set 0, b		; E3W.cls 647
            jr fn_e3w_lib_wvco2		; E3W.cls 648
fn_e3w_lib_wvco1:		; E3W.cls 649
            ex de, hl		; E3W.cls 650
            ld hl, (fn_e3w_lib_ew_wx1)		; E3W.cls 651
            or a		; E3W.cls 652
            sbc hl, de		; E3W.cls 653
            jp p, fn_e3w_lib_wvco2		; E3W.cls 654
            set 1, b		; E3W.cls 655
fn_e3w_lib_wvco2:		; E3W.cls 656
            pop hl                  ; y [657]
            push hl		; E3W.cls 658
            ld de, (fn_e3w_lib_ew_wy0)		; E3W.cls 659
            or a		; E3W.cls 660
            sbc hl, de		; E3W.cls 661
            jp p, fn_e3w_lib_wvco3		; E3W.cls 662
            set 2, b		; E3W.cls 663
            jr fn_e3w_lib_wvco4		; E3W.cls 664
fn_e3w_lib_wvco3:		; E3W.cls 665
            pop de		; E3W.cls 666
            push de		; E3W.cls 667
            ld hl, (fn_e3w_lib_ew_wy1)		; E3W.cls 668
            or a		; E3W.cls 669
            sbc hl, de		; E3W.cls 670
            jp p, fn_e3w_lib_wvco4		; E3W.cls 671
            set 3, b		; E3W.cls 672
fn_e3w_lib_wvco4:		; E3W.cls 673
            pop de		; E3W.cls 674
            pop hl		; E3W.cls 675
            ld a, b		; E3W.cls 676
            ret		; E3W.cls 677
; ew_line2: the line ew_ax, ew_ay - ew_bx, ew_by (16 bit) in ew_col, cut to the box
