;## ntc_rnd_seed
ntc_rnd_seed:	dw 1

ntc_rg391_e:
			IF ($ < 65536) && (ntc_rg392_e - ntc_rg392 + $ > 48640)	; fwdref-ok
			ASSERT ntc_oom, "out of memory: the program does not fit below #BE00 (Option Memory Reserved #BE00-#FFFF is the top of memory)"
